import React, { useCallback } from 'react';
import {
  Button,
  MultiSelectWithOther,
  ButtonProps,
  Text,
  SizeEnum,
  WeightEnum,
} from '@getvim/atomic-ui';
import classNames from 'classnames';
import './index.less';
import RoleSelectIcon from '../../assets/role-select.svg';
interface UpdateRoleFormProps {
  options: string[];
  defaultValues: string[];
  onChange: (values: string[]) => void;
  onSubmit: () => void;
  buttonColor?: ButtonProps['bgColor'];
}

export const UpdateRoleForm = ({
  options,
  defaultValues,
  onChange,
  onSubmit,
  buttonColor = 'default',
}: UpdateRoleFormProps) => {
  const preventDefault = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const renderAddOtherOptions = useCallback(
    (val: string, ctaText: string, props: any, cb: (event: any) => void) => {
      return (
        <li {...props} className="add-new-role-li" onKeyDown={preventDefault} onClick={cb}>
          <div className="add-new-role-container">
            <div className="add-new-role-message">
              <Text text={`${ctaText}: `} size={SizeEnum['13px']} />
              <Text text={val} size={SizeEnum['13px']} weight={WeightEnum.semibold} />
              {ctaText === 'Add' ? <Text text={'as new role'} size={SizeEnum['13px']} /> : null}
            </div>
            <div>
              <Button className="role-add-btn" bgColor="default">
                {ctaText || 'Add'}
              </Button>
            </div>
          </div>
        </li>
      );
    },
    [preventDefault],
  );
  return (
    <div className={classNames('user-center-update-role-form')}>
      <img src={RoleSelectIcon} alt="role-select-icon" className="role-select-icon" />

      <MultiSelectWithOther
        title={'Select role'}
        defaultValues={defaultValues}
        options={options}
        width="100%"
        onChange={onChange}
        emptyOtherText={`Didn't find your role? Start typing to create a new one`}
        height={'36px'}
        renderAddOtherOptions={renderAddOtherOptions}
        hideLabel
        limitTags={3}
        startAdornment={
          <img src={RoleSelectIcon} alt="role-select-icon" className="role-select-icon" />
        }
      />
      <Button
        className="submit-role-button"
        data-test-id="submit-role-button"
        text={'Submit'}
        buttonType="small"
        bgColor={buttonColor}
        width="small"
        onClick={onSubmit}
        style={{ marginLeft: '-0.25rem', zIndex: 0 }}
      />
    </div>
  );
};
